#### Integration Testing (Producer/Consumer)

Test end-to-end event flow:

```csharp
// ClaimsSubmittedTopicIntegrationTests.cs
[TestClass]
public class ClaimsSubmittedTopicIntegrationTests
{
    [TestMethod]
    public async Task ProduceAndConsume_ClaimSubmittedEvent_Success()
    {
        // Arrange
        var topicName = "claims.adjudication.claim.submitted.v1";
        var claimEvent = new ClaimSubmittedEvent
        {
            ClaimId = "CLM-12345",
            MemberId = "MEM-67890",
            SubmittedAt = DateTimeOffset.UtcNow,
            ClaimAmount = 150.00m
        };

        // Act - Produce
        await _producer.ProduceAsync(topicName, claimEvent);

        // Act - Consume
        var consumed = await _consumer.ConsumeAsync(topicName, TimeSpan.FromSeconds(10));

        // Assert
        Assert.IsNotNull(consumed);
        Assert.AreEqual(claimEvent.ClaimId, consumed.ClaimId);
        Assert.AreEqual(claimEvent.MemberId, consumed.MemberId);
    }

    [TestMethod]
    public void Producer_CompressionEnabled_SnappyCompression()
    {
        // Arrange
        var config = _producer.Config;

        // Assert
        Assert.AreEqual("snappy", config[ProducerConfig.CompressionType]);
    }
}
```
